-- Local metadata fixtures, not actual Storage HTTP/blob tests.
begin;
create function pg_temp.assert_true(v boolean,label text) returns void language plpgsql as $$begin if v is distinct from true then raise exception 'FAIL: %',label;end if;end;$$;
create function pg_temp.expect_error(q text,code text) returns void language plpgsql as $$declare actual text;begin begin execute q;exception when others then get stacked diagnostics actual=returned_sqlstate;if actual<>code then raise exception 'FAIL expected %, got %: %',code,actual,q;end if;return;end;raise exception 'FAIL expected rejection: %',q;end;$$;
insert into auth.users(id) values('f1000000-0000-4000-8000-000000000001'),('f1000000-0000-4000-8000-000000000002');
create function pg_temp.ci(n integer) returns uuid language sql as $$select ('f2000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
create function pg_temp.cm(n integer) returns uuid language sql as $$select ('f3000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
create function pg_temp.cp(n integer,owner_id text default 'f1000000-0000-4000-8000-000000000001',draft integer default 1) returns text language sql as $$select owner_id||'/chat/f4000000-0000-4000-8000-000000000001/'||pg_temp.cm(draft)::text||'/'||pg_temp.ci(n)::text||'.jpg'$$;
create function pg_temp.cs(n integer,body text default '',images jsonb default jsonb_build_array(pg_temp.ci(1),pg_temp.ci(2))) returns public.request_messages language sql as $$select public.send_request_image_message(pg_temp.cm(n),'f4000000-0000-4000-8000-000000000001',body,images)$$;
create function pg_temp.fail_image_alert() returns trigger language plpgsql as $$begin if new.message_id=pg_temp.cm(1) and current_setting('test.fail_image_alert',true)='yes' then raise exception 'Injected notification failure' using errcode='23514';end if;return new;end;$$;
create trigger fail_image_alert before insert on public.request_notifications for each row execute function pg_temp.fail_image_alert();
select pg_temp.assert_true((select not public and file_size_limit=5242880 and allowed_mime_types=array['image/jpeg','image/png','image/webp'] from storage.buckets where id='request-chat-images'),'separate private chat bucket with limits');
set local role authenticated;
select set_config('request.jwt.claim.sub','50000000-0000-4000-8000-000000000002',true);
select public.initialize_tailor_profile();
select public.save_tailor_profile('{"shop_name":"Image Atelier","description":"Bespoke garments for special occasions.","specialties":"Dresses","city":"Colombo","public_address":"123 Public Street","business_phone":"+94112223344","years_experience":5,"accepting_requests":true}',true,1);
select set_config('request.jwt.claim.sub','f1000000-0000-4000-8000-000000000001',true);
select public.send_tailoring_request('f4000000-0000-4000-8000-000000000001','50000000-0000-4000-8000-000000000002','dress','Please discuss image inspiration.',1,current_date+30);
select public.send_tailoring_request('f4000000-0000-4000-8000-000000000002','50000000-0000-4000-8000-000000000002','dress','A different private conversation.',1,current_date+30);
do $$begin for n in 1..3 loop perform public.reserve_chat_image(pg_temp.ci(n),'f4000000-0000-4000-8000-000000000001',pg_temp.cm(1),'jpg');end loop;end;$$;
select public.reserve_chat_image(pg_temp.ci(1),'f4000000-0000-4000-8000-000000000001',pg_temp.cm(1),'jpg');
-- Reproduce Storage's authorization probe before corrective migration 023.
-- Its declared contentLength is not the completed metadata.size.
select pg_temp.expect_error($q$insert into storage.objects(bucket_id,name,metadata) values('request-chat-images',pg_temp.cp(1),'{"contentLength":100,"mimetype":"image/jpeg"}')$q$,'42501');
select pg_temp.expect_error($q$select public.reserve_chat_image(pg_temp.ci(4),'f4000000-0000-4000-8000-000000000001',pg_temp.cm(1),'jpg')$q$,'22023');
select pg_temp.expect_error($q$select public.reserve_chat_image(pg_temp.ci(4),'f4000000-0000-4000-8000-000000000001',pg_temp.cm(2),'svg')$q$,'22023');
select pg_temp.expect_error('select pg_temp.cs(1)','22023');
select pg_temp.expect_error($q$insert into storage.objects(bucket_id,name,metadata) values('request-chat-images',pg_temp.cp(1),'{"size":5242881,"mimetype":"image/jpeg"}')$q$,'42501');
select pg_temp.expect_error($q$insert into storage.objects(bucket_id,name,metadata) values('request-chat-images',pg_temp.cp(1),'{"size":0,"mimetype":"image/jpeg"}')$q$,'42501');
select pg_temp.expect_error($q$insert into storage.objects(bucket_id,name,metadata) values('request-chat-images',pg_temp.cp(1),'{"size":100,"mimetype":"image/png"}')$q$,'42501');
select pg_temp.expect_error($q$insert into storage.objects(bucket_id,name,metadata) values('request-chat-images',pg_temp.cp(4),'{"size":100,"mimetype":"image/jpeg"}')$q$,'42501');
insert into storage.objects(bucket_id,name,metadata) values('request-chat-images',pg_temp.cp(1),'{"size":5242880,"mimetype":"image/jpeg"}'),('request-chat-images',pg_temp.cp(2),'{"size":100,"mimetype":"image/jpeg"}'),('request-chat-images',pg_temp.cp(3),'{"size":100,"mimetype":"image/jpeg"}');
select pg_temp.expect_error($q$select pg_temp.cs(1,'',jsonb_build_array(pg_temp.ci(1),pg_temp.ci(1)))$q$,'22023');
select pg_temp.expect_error($q$select pg_temp.cs(1,'',jsonb_build_array(pg_temp.ci(1),pg_temp.ci(2),pg_temp.ci(3),pg_temp.ci(4)))$q$,'22023');
select pg_temp.expect_error($q$select pg_temp.cs(1,'','[{"id":"forged","image_path":"evil"}]')$q$,'22023');
select pg_temp.expect_error($q$select pg_temp.cs(1,repeat('x',2001))$q$,'22023');
select pg_temp.expect_error($q$select public.send_request_image_message(pg_temp.cm(1),'f4000000-0000-4000-8000-000000000002','',jsonb_build_array(pg_temp.ci(1)))$q$,'42501');
select pg_temp.expect_error('select pg_temp.cs(2)','42501');
select set_config('test.fail_image_alert','yes',true);
select pg_temp.expect_error('select pg_temp.cs(1)','23514');
select pg_temp.assert_true((select count(*)=0 from public.request_messages),'message and attachments roll back on notification failure');
select pg_temp.assert_true((select bool_and(message_id is null) from public.chat_image_uploads),'upload locks roll back with message');
select set_config('test.fail_image_alert','no',true);
do $$declare before_row jsonb;begin select to_jsonb(r) into before_row from public.tailoring_requests r where id='f4000000-0000-4000-8000-000000000001';perform pg_temp.cs(1);perform pg_temp.assert_true(before_row=(select to_jsonb(r) from public.tailoring_requests r where id='f4000000-0000-4000-8000-000000000001'),'image message never changes request agreement, snapshots, dates or stages');end;$$;
select pg_temp.cs(1);
select pg_temp.assert_true((select count(*)=1 and bool_and(body='' and jsonb_array_length(images)=2 and images->0->>'id'=pg_temp.ci(1)::text and images->1->>'id'=pg_temp.ci(2)::text) from public.request_messages),'image-only message freezes ordered paths once');
select pg_temp.expect_error($q$select pg_temp.cs(1,'changed')$q$,'22023');
select pg_temp.expect_error($q$select pg_temp.cs(1,'',jsonb_build_array(pg_temp.ci(2),pg_temp.ci(1)))$q$,'22023');
select pg_temp.expect_error($q$select public.send_request_message(pg_temp.cm(1),'f4000000-0000-4000-8000-000000000001','')$q$,'22023');
select pg_temp.expect_error('update public.request_messages set images=''[]''','42501');
select pg_temp.expect_error('delete from public.chat_image_uploads','42501');
select pg_temp.expect_error('select public.release_chat_image(pg_temp.ci(1))','22023');
update storage.objects set metadata='{"size":5,"mimetype":"image/jpeg"}' where bucket_id='request-chat-images';
delete from storage.objects where bucket_id='request-chat-images' and name=pg_temp.cp(1);
select pg_temp.assert_true((select metadata->>'size'='5242880' from storage.objects where bucket_id='request-chat-images' and name=pg_temp.cp(1)),'sent images cannot be overwritten or deleted');
delete from storage.objects where bucket_id='request-chat-images' and name=pg_temp.cp(3);
select public.release_chat_image(pg_temp.ci(3));
select public.reserve_chat_image(pg_temp.ci(4),'f4000000-0000-4000-8000-000000000001',pg_temp.cm(2),'jpg');
reset role;update public.chat_image_uploads set created_at=now()-interval '2 hours';set local role authenticated;
select pg_temp.assert_true((select count(*)=1 and bool_and(id=pg_temp.ci(4)) from public.unused_chat_images()),'cleanup lists only aged caller unreferenced uploads');
select pg_temp.assert_true((select count(*)=0 from public.unused_chat_images(pg_temp.cm(2))),'cleanup excludes current draft');
select set_config('request.jwt.claim.sub','f1000000-0000-4000-8000-000000000002',true);
select pg_temp.assert_true((select count(*)=0 from storage.objects where bucket_id='request-chat-images'),'unrelated customer cannot sign/list/download');
select pg_temp.assert_true((select count(*)=0 from public.request_messages),'unrelated customer cannot read paths or captions');
select pg_temp.expect_error($q$select public.reserve_chat_image(pg_temp.ci(5),'f4000000-0000-4000-8000-000000000001',pg_temp.cm(2),'jpg')$q$,'42501');
select pg_temp.expect_error('select pg_temp.cs(1)','42501');
select pg_temp.expect_error('select public.chat_image_ready(pg_temp.ci(1))','42501');
select pg_temp.assert_true((select count(*)=0 from public.unused_chat_images()),'no foreign cleanup');
select set_config('request.jwt.claim.sub','50000000-0000-4000-8000-000000000002',true);
select pg_temp.assert_true((select count(*)=2 from storage.objects where bucket_id='request-chat-images'),'tailor sees sent images only');
select pg_temp.assert_true((select unread=1 from public.request_message_summaries(array['f4000000-0000-4000-8000-000000000001'::uuid])),'image-only messages count as one unread');
select pg_temp.assert_true((select count(*)=1 from public.request_notifications where kind='message_received'),'one notification after retries');
select public.mark_request_messages_read('f4000000-0000-4000-8000-000000000001',1);
select public.reserve_chat_image(pg_temp.ci(5),'f4000000-0000-4000-8000-000000000001',pg_temp.cm(3),'jpg');
insert into storage.objects(bucket_id,name,metadata) values('request-chat-images',pg_temp.cp(5,'50000000-0000-4000-8000-000000000002',3),'{"size":100,"mimetype":"image/jpeg"}');
select pg_temp.expect_error($q$select pg_temp.cs(3,'',jsonb_build_array(pg_temp.ci(4)))$q$,'42501');
select pg_temp.cs(3,'  Tailor caption  ',jsonb_build_array(pg_temp.ci(5)));
select pg_temp.assert_true((select body='Tailor caption' and sender_id=auth.uid() from public.request_messages where id=pg_temp.cm(3)),'tailor image caption and sender derived server-side');
select public.send_request_message(pg_temp.cm(4),'f4000000-0000-4000-8000-000000000001','Legacy text still works');
reset role;
update public.tailoring_requests set status='cancelled',cancelled_at=now() where id='f4000000-0000-4000-8000-000000000001';
set local role authenticated;
select pg_temp.cs(3,'Tailor caption',jsonb_build_array(pg_temp.ci(5)));
select pg_temp.expect_error($q$select public.reserve_chat_image(pg_temp.ci(6),'f4000000-0000-4000-8000-000000000001',pg_temp.cm(6),'jpg')$q$,'22023');
select pg_temp.expect_error($q$select pg_temp.cs(6,'New message','[]')$q$,'22023');
select pg_temp.assert_true((select count(*)=3 from storage.objects where bucket_id='request-chat-images'),'terminal history keeps participant image access');
select set_config('request.jwt.claim.sub','f1000000-0000-4000-8000-000000000001',true);
select pg_temp.expect_error($q$insert into storage.objects(bucket_id,name,metadata) values('request-chat-images',pg_temp.cp(4,'f1000000-0000-4000-8000-000000000001',2),'{"size":100,"mimetype":"image/jpeg"}')$q$,'42501');
reset role;
update public.tailoring_requests set status='rejected',cancelled_at=null,responded_at=now(),rejection_reason='Cannot take this work.' where id='f4000000-0000-4000-8000-000000000001';
set local role authenticated;
select pg_temp.expect_error($q$select pg_temp.cs(6,'After rejection','[]')$q$,'22023');
select pg_temp.expect_error($q$select public.reserve_chat_image(pg_temp.ci(6),'f4000000-0000-4000-8000-000000000001',pg_temp.cm(6),'jpg')$q$,'22023');
reset role;
update public.tailoring_requests set status='accepted',rejection_reason=null,completed_at=now() where id='f4000000-0000-4000-8000-000000000001';
set local role authenticated;
select pg_temp.cs(1);
select pg_temp.expect_error($q$select pg_temp.cs(6,'After completion','[]')$q$,'22023');
select pg_temp.expect_error($q$insert into storage.objects(bucket_id,name,metadata) values('request-chat-images',pg_temp.cp(4,'f1000000-0000-4000-8000-000000000001',2),'{"size":100,"mimetype":"image/jpeg"}')$q$,'42501');
reset role;
create policy test_broad_chat_images on storage.objects for all to authenticated using(true) with check(true);
set local role authenticated;
select set_config('request.jwt.claim.sub','f1000000-0000-4000-8000-000000000002',true);
select pg_temp.assert_true((select count(*)=0 from storage.objects where bucket_id='request-chat-images'),'restrictive guards defeat broad legacy policies');
select pg_temp.expect_error($q$insert into storage.objects(bucket_id,name,metadata) values('request-chat-images',pg_temp.cp(4,'f1000000-0000-4000-8000-000000000001',2),'{"size":100,"mimetype":"image/jpeg"}')$q$,'42501');
delete from storage.objects where bucket_id='request-chat-images';
reset role;set local role anon;
select pg_temp.assert_true((select count(*)=0 from storage.objects where bucket_id='request-chat-images'),'anonymous Storage access denied');
select pg_temp.expect_error('select * from public.chat_image_uploads','42501');
reset role;rollback;
select 'PASS: private chat images, participant access, immutable atomic messages, retry, limits, cleanup and legacy text' as result;
